-- ===== 본문 재추출 반영 2번 파일 분할 2b (id 231~299, 35행) =====

UPDATE public.words SET meaning = '배당할인모형(Dividend Discount Model)은 주식투자에 따라 발생하는 미래의 현금흐름을 적절한 할인율을 적용하여 현재가치로 전환함으로써 주식의 현재가치를 평가하는 모형이다.', detailed_meaning = '배당할인모형(Dividend Discount Model)은 주식투자에 따라 발생하는 미래의 현금흐름을 적절한 할인율을 적용하여 현재가치로 전환함으로써 주식의 현재가치를 평가하는 모형이다. 주식투자에 따른 현금흐름은 보유기간 중의 배당금과 매도할 경우의 주식가격으로 구성되는데 만일 보유기간이 매우 길다면 매도할 주식가격의 현재가치는 0에 수렴하게 된다. 일반적으로 주식은 만기가 없는 영구적인 증권이므로 보유기간을 무한대로 상정할 수 있다. 따라서 주식의 가치는 각 기별 배당금을 적절한 할인율(주식투자의 요 구수익률이라고 함)로 할인한 현재가치의 합으로 볼 수 있다. 배당할인모형은 주식가치평가모형 중 가장 기본적인 모형으로서 주식가격 형성에 있어서 핵심 요인이 무엇인지를 보여준다. 그러나 기업경영 및 이익에 관한 수많은 불확실성 등으로 인해 먼 미래의 배당금을 추정하는 것은 불가능에 가깝다. 이러한 문제점을 극복하기 위해 Myron Gordon은 배당금이 일정률로 성장한다는 가정을 기초로 정률성장배당할인모형(Constant Growth Dividend Discount Model)을 제시하였다. Gordon의 모형에 따르면 현재 주식의 가치 (P0), 최근 예상배당(D1), 주식투자의 요구수익률(r), 배당성장률(g) 간에는 P0=D1/(r-g) 의 관계가 성립한다. ㅂ', related_words = ARRAY['배당금','할인율']::text[] WHERE id = 231;  -- 배당할인모형
UPDATE public.words SET meaning = '법정화폐(Legal Tender)란 법률에 의해 인정되는 공적 지불수단의 성격을 지닌 화폐를 의미한다.', detailed_meaning = '법정화폐(Legal Tender)란 법률에 의해 인정되는 공적 지불수단의 성격을 지닌 화폐를 의미한다. 다시 말해 국가가 법률로 부채의 상환, 상품 구매, 세금 납부 등에 있어서 반드시 수령하고 경제적 거래가 완결됨을 의미한다. 국가마다 법정화폐로 인정되는 범위가 다 른데 우리나라의 경우 한국은행법 제48조에서 “한국은행이 발행한 한국은행권은 법화(法 貨)로서 모든 거래에 무제한 통용된다.”고 규정함으로써 한국은행권이 모든 경제적 거래에서 법정화폐로 인정된다. 그러나 법정화폐 수령 거부에 대한 처벌 조항이 없는 데다 신용카드, 실시간 계좌이체 등 전자결제 수단에 대한 선호, 큰 금액의 채무를 소액 주화를 대량으로 지급하여 수령인의 불편을 초래하는 행위에 대한 사회적 반감 등으로 한국은행권이 완전한 법정화폐로서 기능하는 데에는 현실적인 한계가 존재한다.', related_words = '{}'::text[] WHERE id = 235;  -- 법정화폐
UPDATE public.words SET meaning = '변동금리란 시장금리를 반영하여 일정 주기별로 약정금리가 변하는 금리를 의미하며, 고 정금리란 최초 약정한 금리가 만기 때까지 그대로 유지되는 금리를 의미한다.', detailed_meaning = '변동금리란 시장금리를 반영하여 일정 주기별로 약정금리가 변하는 금리를 의미하며, 고 정금리란 최초 약정한 금리가 만기 때까지 그대로 유지되는 금리를 의미한다. 예를 들어 만기 1년, 약정금리는 4%의 고정금리라면 약정기간 1년 동안 시장금리가 어떻게 변하더라도 해당 약정금리는 4%이다. 반면 만기 1년, 변동주기 3개월, 약정금리는 CD금리+0.5%(또는 50bp)의 변동금리라면 3개월에 한 번씩 변동된 CD금리에 연동하여 약정금리가 변하게 된다. 예를 들어 CD금리가 최초 약정시 3.0%, 약정 3개월 후 3.2%, 6개월 후 3.5%, 9개월 후 4.0%라면 약정금리는 최초 약정시 3.5%, 약정 3개월 후 3.7%, 6개월 후 4.0%, 9개월 후 4.5%가 된다. 자금 차입자 입장에서는 앞으로 시장금리가 상승할 것으로 예상하는 경우에는 고정금리를 이용하는 것이 유리하고 시장금리가 하락할 것으로 예상하는 경우에는 변동금리를 이용하는 것이 유리하다. 일반적으로 동일 만기에서 는 고정금리가 변동금리보다 높은데 이는 자금 대여자(은행)에게 약정 기간 중 금리 변동에 따른 위험 프리미엄이 존재하기 때문이다. 한편 변동금리의 준거가 되는 금리는 CD금리가 주로 적용되었으나 지금은 COFIX와 은행채 금리도 많이 활용되고 있다.', related_words = ARRAY['고정금리','자금조달비용지수(COFIX)']::text[] WHERE id = 238;  -- 변동금리
UPDATE public.words SET meaning = '보복소비(Revenge Spending 혹은 Pent-up Demand)란 상당 기간 소비 기회가 막혀 강제적으로 소비가 제한되거나 혹은 소비가 억제됨에 따른 피로 누적과 이에 대한 보상욕구,', detailed_meaning = '보복소비(Revenge Spending 혹은 Pent-up Demand)란 상당 기간 소비 기회가 막혀 강제적으로 소비가 제한되거나 혹은 소비가 억제됨에 따른 피로 누적과 이에 대한 보상욕구, 미래 소비기회 상실 우려 등에 대한 반작용으로 소비가 급격하게 늘어나는 것을 의 미한다. 최근 코로나19로 억눌렸던 소비 욕구 및 수요가 보복하듯 한꺼번에 분출하는 현상을 지칭하기 위하여 널리 쓰여지게 되었다. 2020년 중국 언론과 소비 트렌드 분석에서 처음 부각된 것으로 알려져 있다.', related_words = '{}'::text[] WHERE id = 239;  -- 보복소비
UPDATE public.words SET meaning = '국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 기본자본에 비해 손실흡수능력이 떨어지지만 예상외 손실로 은행이 파산할 경우예금자를 포함한', detailed_meaning = '국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 기본자본에 비해 손실흡수능력이 떨어지지만 예상외 손실로 은행이 파산할 경우예금자를 포함한 일반채권자에 앞서 손실을 흡수(혹은 은행의 청산 시 은행의 손실을 보전)할 수 있는 자기자본(gone-concern capital)을 의미한다. 보완자본은 해당하는 요건 ㅂ을 충족하는 보완자본증권 및 이와 관련된 자본잉여금, 자회사가 발행한 보완자본증권의 일부 제3자 보유분, 특정 요건을 충족하는 대손충당금 등으로 구성된다. 해당 은행이 발행한 증권이 보완자본증권으로 인정받기 위해서는 예금자·일반채권자보다 후순위일 것,최저만기 5년 이상이고 금리 상향조정을 비롯한 중도상환 유인이 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3). 아울러 신용리스크 측정시 표준방법을 사용하는 은행이 설정한 일반 대손충당금(general provisions)과 내부등급법 사용은행이 예상손실을 초과하여 적립한 적격 대손충당금은 규제자본과 동일하게 예상외 손실을 흡수하는 데 사용할 수 있다고 간주하여 일정 범위(각각 신용위험가중자산의 1.25% 및 0.6%) 내에서 보완자본(supplementary capital)에 가산할 수 있다.', related_words = ARRAY['BIS 자기자본비율','기본자본(Tier 1)']::text[] WHERE id = 240;  -- 보완자본(Tier 2)
UPDATE public.words SET meaning = '보통주자본(CET1; Common Equity Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 핵심 요소로서, 손실흡수능력이 가장 높은(혹은 은행의 손실을 가장 먼저 보전할', detailed_meaning = '보통주자본(CET1; Common Equity Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 핵심 요소로서, 손실흡수능력이 가장 높은(혹은 은행의 손실을 가장 먼저 보전할 수 있는) 자본을 의미하며 보통주 발행으로 인한 자본금·자본잉여금, 이익잉여금, 기타포괄손익누계액 등으로 구성된다. 특정 자본이 보통주자본으로 인정받기 위해서는 청산시 최후 순위일 것, 영구적일 것, 청산시를 제외하고는 상환불가, 재매입 및 상환 또는 발행취소에 대한 기대가 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3). 바젤Ⅲ에서는 보통주자본비율을 위험가중자산의 4.5% 이상이 되도록 규정하고 있다.', related_words = ARRAY['기본자본(Tier 1)','기타기본자본(Additional Tier 1)']::text[] WHERE id = 242;  -- 보통주자본(Common Equity Tier 1)
UPDATE public.words SET meaning = '보호무역주의는 국가간 무역을 제한하는 경제정책이다.', detailed_meaning = '보호무역주의는 국가간 무역을 제한하는 경제정책이다. 주된 수단으로는 수입금지나 수입할당과 같은 직접적인 방법과 수입상품에 대한 관세 부과와 같은 간접적인 방법 이외에도 덤핑 규제, 보조금 지급, 지적재산권 보호 강화, 환율조작 등 기타 다양한 정부의 규제 등이 있다. 보호무역주의의 목적은 수입으로 경쟁이 유발되는 산업의 생산, 유통, 고용 등에 손해가 발생하지 않도록 하는 것이다. 한편 보호무역주의는 상대국 수출부문의 생산, 고용은 물론 동 정책을 실행하는 국가의 소비자에게도 물가 상승과 같은 부정적 영향을 미친다. 보호무역주의의 순효과는 경제의 성장이나 발전에 부정적이라는 견해가 지배적이어서 선진국의 주도하에 세계적으로 무역장벽을 낮추는 추세를 보여 왔다. 그러나 일부에서 무역수지 흑자국과 적자국이 뚜렷이 구분·지속되고 수지폭도 점점 커지면서 단기적으로 적자국 수입경쟁 부문의 고용이 심각한 불균형을 보이는 등 부작용도 확대되었다. 이러한 부작용은 특히 2008년 발생한 글로벌 금융위기의 한 원인으로 지적되기도 했 다. 최근 미국이 보호무역을 강화하는 정책을 실시하면서 무역갈등이 심화되고 있으나 G20의 대부분 국가는 보호무역주의의 확산을 경계하고 있다.', related_words = ARRAY['긴급수입제한조치']::text[] WHERE id = 244;  -- 보호무역주의
UPDATE public.words SET meaning = '복수통화바스켓제도란 자국과 교역 비중이 큰 복수국가의 통화를 선택하여 통화군(바스켓)을 구성하고 바스켓(basket)을 구성하는 통화들의 가치가 변동할 경우 각 통화별 교역가중치에 따라 자국통화의', detailed_meaning = '복수통화바스켓제도란 자국과 교역 비중이 큰 복수국가의 통화를 선택하여 통화군(바스켓)을 구성하고 바스켓(basket)을 구성하는 통화들의 가치가 변동할 경우 각 통화별 교역가중치에 따라 자국통화의 환율에 반영하는 환율제도를 말한다. 복수통화바스켓제도 는 자국 통화의 가치가 달러화 같은 특정 외국 통화에 고정되는 것이 아니라 바스켓에 포함된 여러 통화의 가치 변화에 따라 변동하게 하여 환율의 안정성을 도모하는 동시에 환율이 주요 교역상대국과의 경쟁력을 종합적으로 반영하게 하는 장점이 있다. 우리나라는 1980년 2월부터 복수통화바스켓제도를 시행한 바 있으며, 당시 원/달러 환율은 SDR의 대미달러화 환율인 SDR바스켓과 우리나라의 주요 교역상대국인 미국, 일본, 서독, 영국, 프랑스 통화의 미달러화에 대한 환율변동을 가중평균한 독자바스켓, 그리고 정책조정변수인 실세반영장치의 세 가지 요소에 의해 결정되었다. 이후 점차 정책당국의 영향력 때문에 환율이 외환 수급을 적절히 반영하지 못할 수 있다는 우려가 커짐에 따라, 1990년 3 월 정부는 환율 결정에 시장 원리를 보다 폭넓게 반영하기 위하여 시장평균환율제도로 이 행하였다.', related_words = ARRAY['고정환율제도/자유변동환율제도','미달러화페그제도']::text[] WHERE id = 245;  -- 복수통화바스켓제도
UPDATE public.words SET meaning = '제도단위(비금융법인, 금융법인, 일반정부, 가계 및 비영리단체)가 생산과정에 참여하거나 생산활동에 제공된 자산을 소유함에 따라 발생하는 소득으로 국민순소득(NNI; Net National', detailed_meaning = '제도단위(비금융법인, 금융법인, 일반정부, 가계 및 비영리단체)가 생산과정에 참여하거나 생산활동에 제공된 자산을 소유함에 따라 발생하는 소득으로 국민순소득(NNI; Net National Income)이라고도 한다. 이는 생산에 의해 창출된 부가가치에서 지급된다. 구체적으로 본원소득은 피용자보수에 영업잉여, 순생산 및 수입세, 순수취재산소득을 더하여 계산한다. 본원소득 = 피용자보수 + 영업잉여 + 순생산 및 수입세 + 순수취재산소득', related_words = ARRAY['영업잉여','피용자보수']::text[] WHERE id = 247;  -- 본원소득
UPDATE public.words SET meaning = '본원소득수지는 급료 및 임금 수지와 투자소득수지로 구분된다.', detailed_meaning = '본원소득수지는 급료 및 임금 수지와 투자소득수지로 구분된다. 급료 및 임금 수지는 외국인 근로자에게 지급되거나 내국인 해외근로자가 수취하는 금액의 차이를 의미한다. 투자소득수지는 대외 금융자산과 부채의 보유에 의해 발생하는 배당금과 이자 등의 수입과 지급의 차이를 말하는데, 투자 형태에 따라 직접투자소득, 증권투자소득, 기타투자소득으로 세분된다.', related_words = ARRAY['본원소득']::text[] WHERE id = 248;  -- 본원소득수지
UPDATE public.words SET meaning = '증권의 부동화(Immobilization)란 실물증권을 중앙예탁기관에 집중 보관하여 매매거래 또는 담보거래 등에 따른 증권의 권리이전을 계좌대체 방식으로 처리함으로써 증권의 실물인도의 필요성을', detailed_meaning = '증권의 부동화(Immobilization)란 실물증권을 중앙예탁기관에 집중 보관하여 매매거래 또는 담보거래 등에 따른 증권의 권리이전을 계좌대체 방식으로 처리함으로써 증권의 실물인도의 필요성을 제거하는 것을 말한다. 증권실물은 이동하지 않고 예탁기관의 장부상 대차기재에 의하여 증권에 대한 권리가 이전됨으로써 실물증권 이동에 따른 분실· 도난의 위험성, 사무처리의 번잡성 등의 문제점을 해결할 수 있다. 한편 증권의 무권화(Dematerialization)란 유가증권에 대한 권리를 표시하는 실물증권을 발행하지 않고 증권에 대한 권리가 오로지 장부(발행기관 및 중앙예탁기관의 계좌)상에 전자기록 형태로 존재하도록 하여 신주발행 및 증권유통에 따른 권리를 이전하는 것을 말한다.', related_words = ARRAY['중앙예탁기관']::text[] WHERE id = 252;  -- 부동화/무권화
UPDATE public.words SET meaning = 'CDO(Collateralized Debt Obligation)란 회사채나 대출채권 등으로 구성된 pool을 기초자산으로 하여 AAA등급에서 equity(non-rated)까지의 다양한', detailed_meaning = 'CDO(Collateralized Debt Obligation)란 회사채나 대출채권 등으로 구성된 pool을 기초자산으로 하여 AAA등급에서 equity(non-rated)까지의 다양한 신용등급으로 발행된 여러 종의 선·후순위 채권을 말하며, 기초자산의 종류에 따라 회사채를 기초자산으로 하는 회사채 담보부증권(CBO; Collateralized Bond Obligation), 대출채권을 기초자산으로 하는 대출채권 담보부증권(CLO; Collateralized Loan Obligation)으로 분류된다. 그리고 발행목적에 따라 주로 은행 등의 금융기관이 재무상태표상에서 위험자산을 제거하기 위하여 발행하는 Balance Sheet CDO와 고수익의 원자산인 대출금, 회사채 등과 선· 후순위 채권 간의 이자차익을 얻기 위해 발행하는 Arbitrage CDO 등이 있다. 미국의 모기지 전문 대출기관들은 2000년대 초중반 부동산 활황을 틈타 대출자금을 조달하기 위하여 모기지 채권이나 주택저당증권(MBS)을 대량으로 발행하였고, 투자은행들이 이를 사들여 합성한 뒤 발행한 채권이 바로 CDO였다. 2007년 주택담보대출 연체율이 높아지면서 이른바 서브프라임 모기지론 사태가 벌어져 채권 가격이 폭락함으로써 주요 금융회사 등 ㅂ 투자자들이 큰 손실을 입고 글로벌 금융위기로 이어지게 되었다.', related_words = ARRAY['CMO']::text[] WHERE id = 254;  -- 부채담보부증권(CDO)
UPDATE public.words SET meaning = '부채를 자기자본으로 나눈 비율로 대표적인 안정성 지표이다.', detailed_meaning = '부채를 자기자본으로 나눈 비율로 대표적인 안정성 지표이다. 이 비율이 낮을수록 재무구조가 건전하다고 판단할 수 있다. 부채비율은 자기자본비율과 역(逆)의 관계에 있어 자기자본비율이 높을수록 부채비율은 낮아지게 된다. 부채에는 차입금, 회사채, 매입채무, 미지급금, 부채성충당금 등이 포함되며, 지급기일 도래 시점에 따라 1년 이내에 지급기일이 도래하는 유동부채, 1년 이후에 지급기일이 도래하는 비유동부채로 분류할 수 있다. 경영자 입장에서는 단기채무 상환의 압박을 받지 않고 투자수익률이 차입금리 등의 조달금리를 상회하는 한 타인자본을 계속 이용하는 것이 유리하다. 그러나 부채비율이 높은 기업은 상대적으로 경기나 금리변동에 취약하다. 현금흐름이 악화되거나 금리가 상승하면 이 자 부담이 커지고 원리금 상환이 어려워질 가능성이 커지기 때문이다. 부채비율 = [(유동부채 + 비유동부채)/자기자본] × 100', related_words = '{}'::text[] WHERE id = 255;  -- 부채비율
UPDATE public.words SET meaning = '분산원장기술(DLT; Distributed Ledger Technology)은 거래정보가 기록된 원장을 특정 기관의 중앙 서버가 아닌 공유(P2P; Peer-to-Peer) 네트워크에 분산하여', detailed_meaning = '분산원장기술(DLT; Distributed Ledger Technology)은 거래정보가 기록된 원장을 특정 기관의 중앙 서버가 아닌 공유(P2P; Peer-to-Peer) 네트워크에 분산하여 다수의 참가 자가 공동으로 기록·관리하는 기술이다. 전통적 금융시스템의 근간을 이루고 있는 중앙집중형(centralized) 시스템은 원장을 집중·관리하는 ‘제3의 기관’(TTP; Trusted Third Party)을 설립하고 해당 기관에 대한 신뢰를 확보하는 방식으로 발전해 왔다. 예컨대 투자자들이 증권회사를 통해 거래하는 주식을 집중·관리하는 ‘한국예탁결제원’(KSD)이 곧제3의 기관이다. 반면 분산원장기술에서는 다수 참여자가 거래내역이 기록된 원장 전체를 각각 분산 보관(decentralized)하고, 거래할 때마다 이를 검증하며 갱신하는 작업을 공동으로 수행한다. 분산원장기술은 가상자산 발행처럼 누구나 접근 가능하고 거래의 기록 및 관리에도 참여할 수 있는 개방형·비허가형(public, permissionless)과 기업내부또는 금융회사간 시스템처럼 허가받은 경우에만 접근할 수 있는 폐쇄형·허가형(private, permissioned)으로 나눌 수 있다. 분산원장기술은 당초 비트코인·이더리움 등 가상자산(virtual asset)의 기반 기술로 개발되었으나, 현재는 동 기술을 다양한 금융서비스에 활용하기 위한 방안을 모색중이다.', related_words = ARRAY['P2P대출','블록체인','비트코인','가상자산']::text[] WHERE id = 257;  -- 분산원장기술
UPDATE public.words SET meaning = '분수효과(Trickle-up Effect, Fountain Effect)란 정부가 경제정책으로 저소득층과 중산층의 소득을 먼저 늘려주면 이들의 소비 확대가 생산과 투자로 이어지면서 전체 경제활동이', detailed_meaning = '분수효과(Trickle-up Effect, Fountain Effect)란 정부가 경제정책으로 저소득층과 중산층의 소득을 먼저 늘려주면 이들의 소비 확대가 생산과 투자로 이어지면서 전체 경제활동이 되살아나고 이로 인해 고소득층의 소득도 늘어날 수 있다는 주장이다. 즉 분수에서 물이 아래에서 위로 솟아나는 것처럼 저소득층에서 시작된 소득과 소비 증대의 효과가 점차상위 계층으로 확산되면서 전체 경제도 좋아질 수 있다는 것이다. 이러한 주장은 영국의 경제학자인 케인즈(J. M. Keynes)가 경제 활성화에 긴요한 총수요 진작을 위해서는 상대적으로 한계소비성향이 높은 저소득층과 중산층에 초점을 맞추어 정부지출을 늘리고 세금을 줄여야 한다는 논리에 근거하고 있다. 이는 분배보다는 성장에, 그리고 저소득층보다는 고소득층에 중점을 두어 경제정책을 운용해야 한다는 낙수효과와는 상반되는 개념이다. ㅂ', related_words = ARRAY['낙수효과']::text[] WHERE id = 258;  -- 분수효과
UPDATE public.words SET meaning = '브레튼우즈체제는 1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다.', detailed_meaning = '브레튼우즈체제는 1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다. 이 협정을 체결하게 된 배경은 1930년대 대공황의 여파로 인한 금본위제도 붕괴, 무역규제 확대, 환율 불안정에 이어 1940년대 국제유동성 부족, 외환규제 확산 등으로 국제통화질서가 위기에 직면하게 되었기 때문이다. 브레튼우즈체제는 국제통화제도의 본질적인 기능인 유동성 공급과 국제수지 조정 메커니즘을 미달러화를 기축통화로 하는 금환본위제도와 조정가능 고정환율제도를 통해서 해결하고자 하였다. 즉 각국은 달러를 대외준비자산으로 보유하고 미국은 다른 나라가 보유한 달러에 대해 금태환을 보장하며, 각국의 고정환율에 조정이 필요한 경우 국제통화기금(IMF)과 협의하여 변경할 수 있도록 하였다. 이를 뒷받침하기 위하여 설립된 국제기구가 IMF와 국제부흥개발은행(IBRD)이다. 1960년대 들어 국제유동성 수준이 미국의 국제수지 상태에 따라 결정되고 환율 변경을 통한 불균형 개선이 쉽지 않은 등의 구조적인 문제가 대두되는 가운데 1971년 미국이 달러화의 금태환을 정지하고 뒤이어 선진국들이 변동환율제도로 이행함에 따라 브레튼우즈체제는 사실상 붕괴되었다. ㅂ', related_words = ARRAY['국제통화기금(IMF)','금본위제','고정환율제도/자유변동환율제도']::text[] WHERE id = 261;  -- 브레튼우즈체제
UPDATE public.words SET meaning = '브렉시트(Brexit)는 영국(Britain)과 탈퇴(Exit)의 합성어로 영국의 유럽연합(EU) 탈퇴를 뜻한다.', detailed_meaning = '브렉시트(Brexit)는 영국(Britain)과 탈퇴(Exit)의 합성어로 영국의 유럽연합(EU) 탈퇴를 뜻한다. 영국은 2016년 6월 23일 유럽연합(EU) 탈퇴 여부에 대한 국민투표 실시를 통해 51.9%의 찬성으로 EU 탈퇴를 결정하였다. 영국 국민들이 EU 탈퇴를 찬성하게 된 배경에는 2008년 글로벌 금융위기 이후 남유럽국가 구제금융 지원, EU의 난민 포용정책 등 으로 영국의 재정부담이 가중되는 가운데 회원국 노동자의 영국 이주에 따라 영국 고용시장이 악화되는 데 대한 불만이 크게 작용하였다. 2017년 3월 영국 정부가 EU 정상회의 (European Council)에 탈퇴 의사를 공식 통보함으로써 탈퇴 협상이 개시되었으며 이후양자간 긴 협상 끝에 2020년 12월 말 공식적인 탈퇴 절차가 완료되었다. 브렉시트 이후수년간 영국 경제는 여러 가지 부정적인 영향을 받았다. 영국의 대EU 수출은 감소한 반면수입은 증가하여 무역적자가 확대되었고, 저임금 이민 노동자 감소로 인한 노동인력 부족과 비EU 이민자 증가 등이 경제·사회적 문제로 대두되고 있다. 이에 따라 브렉시트에 대한 회의적 시각이 커지게 되었다.', related_words = ARRAY['유럽연합(EU)']::text[] WHERE id = 262;  -- 브렉시트(Brexit)
UPDATE public.words SET meaning = '개인이나 기업이 주택구입, 대규모 개발 프로젝트 수행 등을 위해 장기 자금조달이 필요 할 경우, 해당 자금 마련 이전에 일시적으로 소요되는 비용을 충당하기 위해 단기 자금조달 수단으로 이용하는', detailed_meaning = '개인이나 기업이 주택구입, 대규모 개발 프로젝트 수행 등을 위해 장기 자금조달이 필요 할 경우, 해당 자금 마련 이전에 일시적으로 소요되는 비용을 충당하기 위해 단기 자금조달 수단으로 이용하는 것이 브릿지론이다. 마치 다리(bridge) 역할을 하는 자금조달 수단이다. 예를 들어 부동산 개발 사업을 실시할 경우 토지를 매입하는 초기 단계에서 이에 필요한 자금을 본격적인 PF(Project Financing) 대출로 전환되기 이전에 일시적으로 조달하는 용도로 사용된다. 브릿지론은 일반적으로 6개월에서 1년 만기 정도의 단기대출이며 본 PF대출에 비해 금리가 높다. 이는 초기 사업비용 충당이 주목적인 브릿지론의 특성을 감안할 때 리스크가 높은 점이 반영된 것이다.', related_words = '{}'::text[] WHERE id = 264;  -- 브릿지론
UPDATE public.words SET meaning = '비관측경제(NOE; Non-observed Economy)란 국내총생산(GDP)의 추계에 이용되는 기초자료와 행정자료에 누락된 경제활동을 의미한다.', detailed_meaning = '비관측경제(NOE; Non-observed Economy)란 국내총생산(GDP)의 추계에 이용되는 기초자료와 행정자료에 누락된 경제활동을 의미한다. GDP는 원칙적으로 합법적이건 불법적이건 모든 경제적 거래에서 발생한 소득을 포함해야 하나 현실적으로 지하경제나 불법생산 등은 반영하기가 쉽지 않다. 비관측경제는 일반적으로 문제영역(problem areas)에 속하는 활동 때문에 발생한다. 대표적인 경우가 흔히 지하경제(underground economy) 나 은닉경제(hidden economy)로 표현되는 경제활동이다. 이는 조세나 사회적 의무의 회피, 근로안전이나 소비자보호 등 법적·행정적 규제에 따른 비용의 회피를 위하여 은밀하게 이루어진다. 이러한 거래는 세무·통계 당국에 축소 보고되기도 하고 현금거래로만 행해져 아예 누락되기도 한다. 또한 마약, 장물 거래, 성매매 등과 같이 생산물의 내용이 불법적인 경우도 거래내역을 포착하기 힘들다. 불법생산(illegal production)은 판매나 소유 자체가 법에 의해 금지되어 있으나 GDP에는 포함되어야 한다는 것이 국제적으로 합의된 원칙이다. 이 밖에도 “통계적 지하(statistical underground)”라고 불리는 소규모기업이나 자영업자 등에 대한 미흡한 기초통계 자료 등에 의해서도 비관측경제가 존재하게 된다.', related_words = ARRAY['국내총생산(GDP)']::text[] WHERE id = 265;  -- 비관측경제(NOE)
UPDATE public.words SET meaning = '재화나 서비스의 생산과 관련하여 투입요소 비용의 상승에 의해 물가가 지속적으로 오르게 되는 것을 비용인상 인플레이션(Cost-Push Inflation)이라고 한다.', detailed_meaning = '재화나 서비스의 생산과 관련하여 투입요소 비용의 상승에 의해 물가가 지속적으로 오르게 되는 것을 비용인상 인플레이션(Cost-Push Inflation)이라고 한다. 주요 투입요소인 노동, 자본, 원자재 등의 가격이 상승하면 기업은 증가한 생산비용을 가격에 반영시키므로 최종재의 가격이 오르게 되는 것이다. 비용인상 인플레이션은 경제 내의 생산활동을 위축시키면서 유발되므로 사람들의 소득 수준이 악화될 가능성이 크다. 실제로 1970 년대 발생한 2차례의 오일쇼크(석유가격이 급등하여 재화 및 서비스의 생산비가 크게상승했음)로 인해 유발된 비용인상 인플레이션은 이러한 가능성을 보여주고 있다. 당시유가 상승으로 인해 생산비가 증가하면서 생산활동이 위축되고 이로 인해 경기가 둔화되었다.', related_words = ARRAY['수요견인 인플레이션']::text[] WHERE id = 267;  -- 비용인상 인플레이션
UPDATE public.words SET meaning = '비트코인(Bitcoin)은 가상통화(암호통화)이자 디지털 지급시스템 전자 토큰 형태의 가상자산이다.', detailed_meaning = '비트코인(Bitcoin)은 가상통화(암호통화)이자 디지털 지급시스템 전자 토큰 형태의 가상자산이다. 비트코인 시스템은 중앙 저장소 또는 단일 관리자 없이 탈중앙화된 구조로 작동한다. 비트코인은 사토시 나카모토라는 사람(집단)에 의해 만들어진 것으로 알려져 있고 2009년 개방형 소프트웨어로 배포되었다. 이 시스템은 공유형(peer-to-peer)이며, 거래는 중개자 없이 블록체인 소프트웨어를 이용하는 참여자(nodes) 사이에 직접 이뤄진다. 이런 거래들은 공유(P2P) 네트워크상 참여자의 작업증명(proof-of-work)을 통해 검 증되고 공개된 분산원장인 블록체인에 기록된다. 승인된 거래의 새 그룹인 한 블록은 대략 10분에 한 번씩 만들어져서 블록체인에 추가되고 신속하게 모든 참여자에게 보내진다. 비트코인은 컴퓨터 처리 능력(power)을 활용해서 이뤄지는 채굴(mining)에 대한 보상으로 발행되고 있으며, 비트코인을 다른 통화·상품·용역 등과 교환하는 거래도 발생하고 있다. 중앙은행이 발행한 법정화폐가 아닌 비트코인은 비트코인플랫폼에서 거래되며 투자대상으로도 많은 관심을 받고 있다. 또한 익명성으로 자금세탁 등 불법거래에 악용될소지가 많아 일부 국가에서 비트코인 등 가상통화의 거래를 규제하기도 한다. 일본의 경우 비트코인의 거래이익에 대해 세금을 부과한다. 비트코인은 추가되는 한 블록당 새로 6.25비트코인을 보상하는데(2020.5월 기준), 21만개가 채굴될 때(대략 4년)마다 그 보상이 반으로 줄어든다. 비트코인의 총량은 21백만개이며 2140년경 모두 채굴될 것으로 전망된다. 비트코인은 그 시스템의 설계시 그 수량을 한정시켜 놓았기 때문에 원칙적으로 인플레이션에 의해 가치가 떨어질 수 있는 화폐와 다른 속성을 지닌다. 한편 2017년에는 비트코인에서 규칙을 근본적으로 바꾸는 하드포크(hard-fork)가 발생하였고, 이 과정에 서 8월 1일에는 ‘비트코인캐시(BCH)’가, 10월 25일에는 ‘비트코인골드(BTG)’가 새롭게만들어져 기존 비트코인(classic bitcoin)과는 별도로 거래되고 있다.', related_words = ARRAY['가상자산','작업증명','블록체인']::text[] WHERE id = 268;  -- 비트코인
UPDATE public.words SET meaning = '빅맥지수(Big Mac Index)는 각국 통화의 구매력 정도 또는 환율 수준을 측정하기 위해일물일가의 법칙을 햄버거 가격에 적용한 것으로 영국에서 발행되는 주간 경제전문지 이 코노미스트지(The', detailed_meaning = '빅맥지수(Big Mac Index)는 각국 통화의 구매력 정도 또는 환율 수준을 측정하기 위해일물일가의 법칙을 햄버거 가격에 적용한 것으로 영국에서 발행되는 주간 경제전문지 이 코노미스트지(The Economist)에서 1986년 이래 매년 전 세계적으로 판매되고 있는 맥도날드의 빅맥 가격을 비교·분석해서 발표하고 있다. 맥도날도의 빅맥은 전 세계 120개국에서 동일한 재화로 판매되고 있으므로, 이 빅맥지수를 이용하여 일물일가의 법칙 또는 절대적 구매력평가를 간단하게 검증할 수 있는 기회를 독자들에게 제공한다는 취지이 다. 만약 일물일가의 법칙이 완전하게 성립한다면 세계 모든 나라에서 빅맥의 미달러화가격이 동일하여야 하므로 실제 환율과는 다른 구매력평가환율을 산정해 볼 수 있다. 예를 들어 어느 기준시점의 우리나라 빅맥 가격이 5,500원이고 미국에서의 가격은 5.69달러라 하면, 구매력평가이론의 일물일가의 법칙이 성립한다면 원/달러 환율은 967원/달러(=5,500원/5.69달러)가 되어야 한다. 그런데 그 시점의 실제 환율이 1,350원/달러라면빅맥지수로 볼 때 원화는 미달러화 대비 약 28% 저평가되어 있다고 볼 수 있다.', related_words = ARRAY['구매력평가환율','일물일가의 법칙']::text[] WHERE id = 270;  -- 빅맥지수
UPDATE public.words SET meaning = '현재 비어있거나 1개월 안에 새로 채용될 수 있는 일자리 수를 전체 근로자 수와 빈 일자리수의 합으로 나눈 백분율을 의미한다.', detailed_meaning = '현재 비어있거나 1개월 안에 새로 채용될 수 있는 일자리 수를 전체 근로자 수와 빈 일자리수의 합으로 나눈 백분율을 의미한다. 우리나라에서는 고용노동부가 매달 발표하고 있다.', related_words = ARRAY['베버리지 곡선']::text[] WHERE id = 271;  -- 빈일자리율
UPDATE public.words SET meaning = '정보통신기술의 발달로 기업경영활동에서 디지털화가 가속화되고 상호 연결이 확대되어감에 따라 전자상거래나 정보통신기술을 이용하여 이루어지는 활동 중 사이버 상에서 발생하는 예기치 못한 사고로 인해', detailed_meaning = '정보통신기술의 발달로 기업경영활동에서 디지털화가 가속화되고 상호 연결이 확대되어감에 따라 전자상거래나 정보통신기술을 이용하여 이루어지는 활동 중 사이버 상에서 발생하는 예기치 못한 사고로 인해 기업이 부담하게 될 유·무형의 비용이 증가하는 위험을 말한다. 사이버리스크 발생에 따른 유형의 비용에는 자금 분실, 컴퓨터시스템 손상 또는 악성코드 감염, 네트워크 폐쇄에 따른 조업중단, 고객정보 및 디지털자산의 분실, 정보유출에 따른 법적 및 피해자 보상 등이 있으며, 무형의 비용으로는 고객 이탈, 기업 신뢰도 하락, 브랜드 이미지 손상, 핵심기술 유출에 따른 경쟁우위 훼손 등이 있다. 사이버리스크에 대한 대책으로는 사전 대응(secure)과 지속적 경계(vigilant) 및 신속한 복구능력(resilient) 확보가 제시되고 있다. 한편 디지털 정보량의 증대와 클라우드 컴퓨팅 이용 기업의 증가세를 감안할 때 향후 사이버리스크에 대한 노출은 더욱 늘어날 것으로 예상된다.', related_words = '{}'::text[] WHERE id = 273;  -- 사이버리스크
UPDATE public.words SET meaning = '사전적 정책방향 제시는 향후 통화정책 방향에 대해 중앙은행이 명시적으로 시그널을 전달하는 것으로 새로운 정책은 아니다.', detailed_meaning = '사전적 정책방향 제시는 향후 통화정책 방향에 대해 중앙은행이 명시적으로 시그널을 전달하는 것으로 새로운 정책은 아니다. 그러나 글로벌 금융위기 이후 정책금리의 추가 인하가 어렵고 경제여건의 불확실성이 높은 상황에서 주요국 중앙은행이 적극적으로 그 방식을 다양화하여 활용하였다는 점에서 비전통적 통화정책의 일종으로 분류되고 있다. 중앙은행이 정책금리를 상당 기간 낮은 수준으로 유지할 것이라는 사전적 정책방향을 명확히 제시할 경우 단기시장금리의 미래 기대경로를 낮추고 정책금리 경로 관련 불확실성이 줄어들어 기간프리미엄도 축소되면서 장기금리의 하락에 기여할 수 있다. 또한 중앙은 행이 당면한 정책목표 간의 상충관계에 대한 견해를 제시하여 정책목표의 우선순위를 명확히 전달할 수도 있다. 사전적 정책방향 제시는 미래에 대한 예고이기 때문에 정책적으로 유효하기 위해서는 경제주체들의 중앙은행에 대한 신뢰가 긴요하다. 경제·금융 여건이 예상과 다르게 변화하여 중앙은행이 당초 공표한 정책방향을 변경하게 되면 상황에 따라서는 금융시장의 변동성이 오히려 확대되고 중앙은행의 신뢰성에 부정적인 영향을 줄 가 능성이 있다. 또한 사전적 정책방향의 제시내용이 지나치게 복잡하고 이해하기 어려울 경우 오히려 정책운영 방식의 명료성을 제약하고 정책 불확실성이 다시 높아지는 문제가 발생할 수도 있다.', related_words = ARRAY['양적완화정책','제로금리정책','통화정책 커뮤니케이션']::text[] WHERE id = 274;  -- 사전적 정책방향 제시 (Forward Guidance)
UPDATE public.words SET meaning = '상계관세(Countervailing Duties)는 수출국이 수출기업에 보조금이나 장려금을 지급하여지나치게 낮은 가격을 책정할 경우 수입국이 이로 인한 경쟁력 저하를 상쇄하기 위해 부과 하는', detailed_meaning = '상계관세(Countervailing Duties)는 수출국이 수출기업에 보조금이나 장려금을 지급하여지나치게 낮은 가격을 책정할 경우 수입국이 이로 인한 경쟁력 저하를 상쇄하기 위해 부과 하는 관세를 말한다. 즉 수출국 정부의 보조를 받아 가격·품질 면에서 우위를 갖게 된 수입품으로 인해 수입국이 피해를 입거나 피해를 입을 우려가 있는 경우 그 효과를 상쇄할 목적으로 정규관세 이외에 부과하게 된다. 이러한 점에서 상계관세는 수입국 산업의 경쟁력을 유지하기 위한 일종의 차별관세라 할 수 있다. 우리나라에서는 관세법 제57조에 국내산업을 보호할 필요가 있다고 인정되는 경우 상계관세를 부과할 수 있다고 규정하고 있다.', related_words = ARRAY['긴급수입제한조치']::text[] WHERE id = 279;  -- 상계관세
UPDATE public.words SET meaning = '1989년 7월 설립된 상품공동기금(CFC; Common Fund for Commodities)은 1차산품의 수급 안정을 위한 국제협력 증진과 국제상품협정 체결 촉진 및 기능 활성화를 목적으로', detailed_meaning = '1989년 7월 설립된 상품공동기금(CFC; Common Fund for Commodities)은 1차산품의 수급 안정을 위한 국제협력 증진과 국제상품협정 체결 촉진 및 기능 활성화를 목적으로 하고 있다. 주요 기능으로는 국제상품협정에 따른 완충재고 유지를 위한 금융지원, 1차산품의 개발 촉진 및 교역조건 개선을 위한 연구개발 지원, 1차산품에 관한 가맹국 간정보교환 및 정책협의 촉진 등을 들 수 있다. 2021년 말 기준 가맹국은 101개국과 9개 기구(EC, AU, COMESA 등)로 납입자본금은 139.5백만 달러(약정액 기준)이며 출연금은 175.4백만 달러이다. 우리나라는 1989년 7월 설립과 함께 가입하였으며 2021년 말 기준 1,051.8천 달러를 출자하였다.', related_words = ARRAY['세계무역기구(WTO)']::text[] WHERE id = 281;  -- 상품공동기금(CFC)
UPDATE public.words SET meaning = '국내생산자가 국내시장에 공급하는 상품과 서비스의 평균적인 가격변동을 측정하기 위하여 작성되는 물가지수로서 그 대상품목의 포괄범위가 넓어 전반적인 상품과 서비스의 수급 동향이 반영된 일반적인', detailed_meaning = '국내생산자가 국내시장에 공급하는 상품과 서비스의 평균적인 가격변동을 측정하기 위하여 작성되는 물가지수로서 그 대상품목의 포괄범위가 넓어 전반적인 상품과 서비스의 수급 동향이 반영된 일반적인 물가수준의 변동을 측정할 수 있기 때문에 일반목적지수로서 의 성격을 갖는다. 지수작성에 이용되는 가격은 생산자가 제품 한 단위당 실제로 수취하는 기초가격(basic price)이다. 생산자물가지수는 1910년부터 한국은행에서 작성해 오고 있다.', related_words = ARRAY['소비자물가지수(CPI)','기초가격']::text[] WHERE id = 286;  -- 생산자물가지수(PPI)
UPDATE public.words SET meaning = '인공지능, 소위 AI(Artificial Intelligence)는 인간의 학습, 추론, 문제해결, 지각, 의사결정 등 능력을 인공적으로 구현하는 컴퓨터과학의 한 분야로 인간의 지능을 컴퓨터를', detailed_meaning = '인공지능, 소위 AI(Artificial Intelligence)는 인간의 학습, 추론, 문제해결, 지각, 의사결정 등 능력을 인공적으로 구현하는 컴퓨터과학의 한 분야로 인간의 지능을 컴퓨터를 비롯한 여러 장치에 적용한다. 웹검색 기능, 개인비서 서비스, 자율주행장비 등으로 나타나 고 있다. AI는 1956년 미국 다트머스(Dartmouth) 회의에서 등장한 용어로 학문적 과정의 하나로 시작되었으나 이후 과잉기대, 자금조달 문제 등으로 부침을 겪었다. 2020년대 들어 생성형(generative) AI가 발전하면서 AI 붐이 형성되었다. 생성형 AI는 텍스트, 이미지, 음악, 코드 등 새로운 콘텐츠를 생성하는 AI 기술로 기존 AI가 데이터를 분석하거나 분류하는데 중점을 둔 것과 차이가 있다. GPT, DALL-E, Sora 등이 대표적이며 교육, 의 료, 마케팅, 대고객서비스, 개발 및 연구 분야에서 널리 활용되고 있다. 생성형 AI의 대두는 허위정보 생산, 콘텐츠 조작, 사이버 범죄, 저작권 문제 등 의도하지 않은 결과와 피해를 초래하기도 하였다. 생성형 AI가 인류에 미칠 장기적 효과, 잠재적 능력에 대한 고찰이 진행되면서 도덕적 문제를 포함한 여러 쟁점이 제기되었으며 혜택 확대와 함께 기술안전확보 방안 등에 대해 많은 논의가 이루어지고 있다.', related_words = '{}'::text[] WHERE id = 290;  -- 생성형 인공지능(AI)
UPDATE public.words SET meaning = '생활물가지수(CPI for living necessaries)는 체감물가를 파악하기 위해 일상생활에서 구입 빈도가 높고 지출비중이 높아 가격변동을 민감하게 느끼는 생활필수품을 대상으로 작성한', detailed_meaning = '생활물가지수(CPI for living necessaries)는 체감물가를 파악하기 위해 일상생활에서 구입 빈도가 높고 지출비중이 높아 가격변동을 민감하게 느끼는 생활필수품을 대상으로 작성한 지수이다. 개별 소비자들이 느끼는 물가는 개인이 구입하는 품목이나 구입 빈도에 따라 각각 달라 2025년 현재 소비지출비중이 큰 458개 품목의 가격변동을 평균하여 작성하는 소비자물가지수와는 차이가 있다. 통계청은 이러한 지수물가와 체감물가와의 차이를 설명하기 위하여 일반소비자들이 자주 구입하는 품목과 기본생필품을 중심으로 144 개 품목(쌀, 달걀, 배추, 소주 등)을 선정하여 생활물가지수를 작성하고 있다.', related_words = ARRAY['물가지수','소비자물가지수(CPI)']::text[] WHERE id = 291;  -- 생활물가지수
UPDATE public.words SET meaning = '서학개미란 해외, 주로 미국 주식에 직접 투자하는 한국 개인투자자를 일컫는 신조어이 다.', detailed_meaning = '서학개미란 해외, 주로 미국 주식에 직접 투자하는 한국 개인투자자를 일컫는 신조어이 다. ‘서학’은 서양(특히 미국), ‘개미’는 소액을 모아 투자하는 개인투자자를 비유한 표현이 다. 서학개미는 동학개미와 대비되어 생겨난 용어이다. 동학개미는 2020년 코로나19 당시 국내 증시가 급락했을 때 개인투자자들이 대규모 매수에 나서며 증시 방어 역할을 한 현상을 동학농민운동에 빗대어 표현한 신조어다. 2022년 이후 국내 주식시장이 부진해지는 반면 미국 주식시장은 미달러화 강세, 빅테크 기업 성장 등을 배경으로 호조를 지속하자 국내시장에 실망한 개인투자자들이 미국 등 해외 주식투자를 크게 확대해 나갔는데 이 러한 개인투자자들을 서학개미라 일컫게 되었다. 서학개미의 활발한 해외 투자는 달러화수요를 크게 증가시켜 환율상승 요인으로 작용하는 등 국내 외환시장의 변동성을 확대시키는 요인 중 하나로 평가된다.', related_words = '{}'::text[] WHERE id = 294;  -- 서학개미
UPDATE public.words SET meaning = '선물거래(Futures Transactions)란 공인된 거래소에서 품질, 규격 등이 표준화된 상품의 매매계약을 체결하고 일정기간이 경과한 후에 상품의 인수도와 결제가 이루어지는 거래로서', detailed_meaning = '선물거래(Futures Transactions)란 공인된 거래소에서 품질, 규격 등이 표준화된 상품의 매매계약을 체결하고 일정기간이 경과한 후에 상품의 인수도와 결제가 이루어지는 거래로서 매매계약의 성립과 동시에 상품의 인수도와 결제가 이루어지는 현물거래와 구분된 다. 선물거래와 유사한 개념으로 선도계약(forward contracts)이 있다. 선도계약과 선물거래는 기초 상품을 미래의 특정시점에 특정가격으로 사고 팔기로 약정한 계약이라는 점에서 동일한 성격을 가지나 일반적으로 선도계약은 장외시장에서 거래가 이루어지는 반면 선물거래는 정형화된 거래소를 통해 거래가 이루어지고 일일정산한다는 데 차이가 있다. 선물거래대상이 되는 상품에는 곡물, 귀금속, 원유 등 일반상품과 통화, 채권, 주식 등 금융상품이 있다. 선물거래의 특징으로는 ① 거래소에서 정한 표준화된 조건으로 거래가 이루어지므로 거래의 유동성이 높고, ② 모든 거래자는 거래 이행을 보증하기 위해 청산소(clearing house)에 일정 수준 이상의 증거금(margin)을 예치하여야 하며, ③ 거래소에서 거래가 이루어지면 별도의 조직인 청산소가 거래의 결제 및 이행을 보증하므로 계약불이행 위험(default risk)이 거의 없으며, ④ 최종선물가격을 기준으로 가격변동에 따른당일 손익을 매일 정산한다.', related_words = ARRAY['옵션','스왑']::text[] WHERE id = 295;  -- 선물거래
UPDATE public.words SET meaning = '선물환포지션비율 규제는 국내은행과 외국은행 지점의 선물환포지션(선물 외화자산에서 선물 외화부채를 뺀 값)을 자기자본의 일정 비율 이내로 제한하는 규제로 2010년 10월부터 시행된 제도이다.', detailed_meaning = '선물환포지션비율 규제는 국내은행과 외국은행 지점의 선물환포지션(선물 외화자산에서 선물 외화부채를 뺀 값)을 자기자본의 일정 비율 이내로 제한하는 규제로 2010년 10월부터 시행된 제도이다. 2006년 이후 국내은행 및 외은지점의 선물환 거래가 급증한 것이 단기외채 급증을 가져와 2008년 글로벌 금융위기 당시 외환시장 불안과 자본유출입 변동성 확대의 주된 원인으로 지적되었다. 이에 따라 거시건전성 강화와 외환시장 안정, 단기외채 증가 억제를 목표로 선물환포지션비율 규제 제도가 도입되었다. 도입 당시 국내은행 50%, 외국은행 지점 250%였던 선물환포지션비율 한도는 외환 및 금융시장 상황에 따라 수차례 조정되어 왔으며 2024년 12월 20일부터 각각 75%, 375%로 상향되었는데이는 국내은행들이 외화유동성을 보다 원활하게 확보할 수 있도록 하는 조치였다. 이처럼 선물환포지션비율 규제는 외환건전성 관리의 핵심 정책수단으로 사용됐으며 최근에 는 글로벌 환율변동성 확대와 외환수급 불안에 대응하기 위해 한도가 점차 완화되는 추세에 있다.', related_words = '{}'::text[] WHERE id = 297;  -- 선물환포지션비율 규제
UPDATE public.words SET meaning = '선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라', detailed_meaning = '선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라 범용 선불형카드와 단일목적 선불형카드로 구분된 다. 범용 선불형카드는 광범위한 지역에서 상품 또는 서비스 대금의 지급에 사용될 수 있는 반면 단일목적 선불형카드는 일정지역 또는 특정목적으로만 사용될 수 있다. 선불형카드는 신용카드사가 발행하는 선불카드와 은행 등 금융기관이 발행하는 전자화폐, 전자금융업자가 발행하는 선불전자지급수단으로 구분된다. 대부분의 신용카드사들은 사용한도 가 미리 정해져 있어 그 범위내에서 일반 신용카드처럼 물건이나 서비스를 구매할 수 있고 재충전(top-up)도 가능한 기명 선불카드 또는 무기명 선불카드(기프트카드)를 발행하고 있다. 선불전자지급수단은 IC카드형과 네트워크형으로 분류할 수 있는데 IC카드형은 주로 교통부문을 중심으로 이용되고 있으며 네트워크형은 사이버쇼핑몰 등의 대금결제에 ㅅ 주로 사용되고 있다.', related_words = ARRAY['지급수단','직불카드','전자화폐']::text[] WHERE id = 298;  -- 선불카드/선불전자지급수단
UPDATE public.words SET meaning = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다.', detailed_meaning = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다. 경기종합지수는 선행종합지수, 동행종합지수, 후행종합지수 3 개가 작성되고 있으며, 기준년도 수치가 100이 되도록 하여 산출하고 있다. 선행종합지수는 제조업 재고순환지표, 기계류내수출하지수, 국제원자재가격지수, 수출입물가비율, 코스피지수, 장단기금리차, 구인구직비율, 건설주수액, 소비자기대지수 등의 지표처럼 실제경기순환에 앞서 변동하는 개별지표를 가공·종합하여 만든 지수로 향후 경기변동의 단기예측에 이용된다.', related_words = ARRAY['경기종합지수','후행종합지수']::text[] WHERE id = 299;  -- 선행종합지수
